261	const conjunctionParts = (term) => term.split(CONJUNCTION).map((p) => p.trim());
262	
263	// --- pack-declared rules (merge-rules.json) -----------------------------------
264	
265	export const MERGE_RULES_FILE = 'merge-rules.json';
266	
267	const RULE_NAME_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
268	const DECLARED_KEYS = ['name', 'pathMatching', 'excludePathMatching', 'changeKinds', 'editShape', 'coversMountPolicySources'];
269	const CHANGE_KINDS = ['added', 'modified', 'deleted'];
270	const EDIT_SHAPES = ['any', 'removals-only', 'comment-only'];
271	
272	// Regex-as-string in the `/body/flags` form declared-checks.json already uses —
273	// the same inline parse pattern-rules.mjs applies (this module cannot import the
274	// checks engine's private compiler, so the six lines live here and point there).
275	function compileRegex(raw, where) {
276	  const m = /^\/(.*)\/([a-z]*)$/s.exec(String(raw));
277	  if (!m) throw new Error(`${where}: ${JSON.stringify(raw)} is not a /pattern/ regex string`);
278	  return new RegExp(m[1], m[2]);
279	}
280	
281	// One declared rule compiled into the registry shape. Every key is validated and
282	// `changeKinds`/`editShape` are REQUIRED — a matcher whose reach is defaulted is
283	// a matcher nobody decided (the corpus' explicit-over-default rule).
284	export function compileDeclaredRule(spec, where) {
285	  if (spec === null || typeof spec !== 'object' || Array.isArray(spec)) {
286	    throw new Error(`${where}: a merge rule is an object, not ${JSON.stringify(spec)}`);
287	  }
288	  for (const key of Object.keys(spec)) {
289	    if (!DECLARED_KEYS.includes(key)) {
290	      throw new Error(`${where}: "${key}" is not a merge-rule key — the vocabulary is: ${DECLARED_KEYS.join(', ')}`);
291	    }
292	  }
293	  if (typeof spec.name !== 'string' || !RULE_NAME_RE.test(spec.name)) {
294	    throw new Error(`${where}: a merge rule needs a kebab-case "name"`);
295	  }
296	  const pathMatching = compileRegex(spec.pathMatching, `${where} (${spec.name}).pathMatching`);
297	  const exclude = spec.excludePathMatching === undefined
298	    ? null : compileRegex(spec.excludePathMatching, `${where} (${spec.name}).excludePathMatching`);
299	  if (!Array.isArray(spec.changeKinds) || !spec.changeKinds.length
300	      || spec.changeKinds.some((k) => !CHANGE_KINDS.includes(k))) {
301	    throw new Error(`${where} (${spec.name}): "changeKinds" is a non-empty subset of ${CHANGE_KINDS.join(', ')}`);
302	  }
303	  if (!EDIT_SHAPES.includes(spec.editShape)) {
304	    throw new Error(`${where} (${spec.name}): "editShape" must be one of ${EDIT_SHAPES.join(', ')} — declared, never defaulted`);
305	  }
306	  // The one key that may relax the self-widening guard, and only for files under
307	  // the VENDORED MOUNT (see POLICY_SOURCES below): declaring it is an owner
308	  // saying "this task may rewrite the mount, policy definitions included" — the
309	  // adoption/converge grant. `true` only, so it cannot be half-declared.
310	  if (spec.coversMountPolicySources !== undefined && spec.coversMountPolicySources !== true) {
311	    throw new Error(`${where} (${spec.name}): "coversMountPolicySources" takes only \`true\` — omit it otherwise`);
312	  }
313	  return {
314	    name: spec.name,
315	    coversMountPolicySources: spec.coversMountPolicySources === true,
316	    appliesTo(e) {
317	      if (!pathMatching.test(e.file) || (exclude && exclude.test(e.file))) return false;
318	      if (!spec.changeKinds.includes(changeKindOf(e))) return false;
319	      if (spec.editShape === 'removals-only') return changeKindOf(e) !== 'added' && removalsOnly(e.before, e.after);
320	      if (spec.editShape === 'comment-only') return isCommentOnlyChange(e);
321	      return true;
322	    },
323	  };
324	}
325	
326	// The merge rules the ACTIVE packs declare, keyed by name. `packs` are discovered
327	// pack objects (each with `.dir`), `config` the normalized repo config — the pair
328	// both judging surfaces already hold. A broken declaration or a name collision is
329	// an ERROR entry, never a silent drop: a policy naming the broken rule must fail
330	// closed, and the error text is what gets it fixed.
331	export function declaredMergeRules(packs, config) {
332	  const rules = new Map();
333	  const errors = [];
334	  for (const pack of (packs ?? []).filter((p) => p.dir && isActive(p, config))) {
335	    const file = path.join(pack.dir, MERGE_RULES_FILE);
336	    if (!existsSync(file)) continue;
337	    const where = `${pack.id}/${MERGE_RULES_FILE}`;
338	    let specs;
339	    try {
340	      specs = JSON.parse(readFileSync(file, 'utf8'));
341	      if (!Array.isArray(specs)) throw new Error('the file must hold an array of rule objects');
342	    } catch (e) {
343	      errors.push(`${where}: ${e.message}`);
344	      continue;
345	    }
346	    for (const spec of specs) {
347	      try {
348	        const rule = compileDeclaredRule(spec, where);
349	        if (BUILTIN_MERGE_RULES.has(rule.name) || COMPOSITE_POLICIES.has(rule.name) || rules.has(rule.name)) {
350	          throw new Error(`rule name "${rule.name}" is already taken — merge-rule names are one flat namespace`);
351	        }
352	        rules.set(rule.name, rule);
353	      } catch (e) {
354	        errors.push(e.message.startsWith(where) ? e.message : `${where}: ${e.message}`);
355	      }
356	    }
357	  }
358	  return { rules, errors };
359	}
360	
361	// --- policy parsing -----------------------------------------------------------
362	
363	const TERM_NAME_RE = /^(under:\S+|[a-z0-9]+(-[a-z0-9]+)*)$/;
364	
365	// A policy, normalized from any surface it rides — the declaration's string or
366	// array, the item's `Merge:` field, the commit trailer's `a;b;reject:c` — into
367	// { kind: 'nothing' | 'anything' } or { kind: 'rules', allow, reject } or
368	// { kind: 'invalid', reason }. Invalid is a verdict-shaped answer on purpose:
369	// every consumer treats it as "authorizes nothing", loudly.
370	export function normalizePolicy(raw) {
371	  if (raw == null) return { kind: POLICY_NOTHING };
372	  const terms = Array.isArray(raw)
373	    ? raw.map((t) => String(t).trim())
374	    : String(raw).trim().split(';').map((t) => t.trim());
375	  if (terms.length === 1) {
376	    const one = terms[0].toLowerCase();
377	    if (one === POLICY_NOTHING || one === '') return { kind: POLICY_NOTHING };
378	    if (one === POLICY_ANYTHING) return { kind: POLICY_ANYTHING };
379	    // The queue's historical spellings for its one pre-policy authorization.
380	    if (one === 'if-narrow' || one === 'yes' || one === 'true') return normalizePolicy(['narrow-diff']);
381	  }
382	  const allow = [];
383	  const reject = [];
384	  for (const term of terms) {
385	    const isReject = term.startsWith('reject:');
386	    const parts = conjunctionParts(isReject ? term.slice('reject:'.length) : term);
387	    for (const part of parts) {
388	      if (!TERM_NAME_RE.test(part)) {
389	        return { kind: 'invalid', reason: `"${term}" is not a policy term (rule names or under:<dir>, joined with && and optionally reject:-prefixed)` };
390	      }
391	      if (part.startsWith(UNDER_PREFIX) && !underRule(part)) {
392	        return { kind: 'invalid', reason: `"${part}" names no usable repo-relative directory — spell it under:packs/some-pack` };
393	      }
394	    }
395	    // A composite is itself a union, so intersecting one is ambiguous, and the
396	    // whole-policy words mean nothing narrowed: both are authoring errors.
397	    if (parts.length > 1) {
398	      const notIntersectable = parts.find((p) => COMPOSITE_POLICIES.has(p) || p === POLICY_ANYTHING || p === POLICY_NOTHING);
399	      if (notIntersectable) {
400	        return { kind: 'invalid', reason: `"${notIntersectable}" cannot sit in an && term — intersect specific rules` };
401	      }
402	    }
403	    const name = parts.join(CONJUNCTION);
404	    if (isReject) {
405	      if (COMPOSITE_POLICIES.has(name)) return { kind: 'invalid', reason: `"${term}" rejects a composite — name the specific rules to reject` };
406	      reject.push(name);
407	    } else if (name === POLICY_ANYTHING) {
408	      allow.push(name);
409	    } else if (name === POLICY_NOTHING) {
410	      return { kind: 'invalid', reason: `"nothing" cannot sit in a rule list — it is a whole policy of its own` };
411	    } else {
412	      allow.push(...(COMPOSITE_POLICIES.get(name) ?? [name]));
413	    }
414	  }
415	  if (!allow.length) {
416	    return { kind: 'invalid', reason: 'the policy lists no allow term — "anything except X" is spelled ["anything", "reject:X"]' };
417	  }
418	  return { kind: 'rules', allow: [...new Set(allow)], reject: [...new Set(reject)] };
419	}
420	
421	// The string form of a declared policy — what rides the commit trailer and the
422	// worker's CLI invocation. Inverse of normalizePolicy for every legal value, and
423	// the one place whitespace around `&&` is collapsed, which is what keeps the
424	// stamped trailer a single whitespace-free token.
425	export const policyExpression = (policy) =>
426	  (Array.isArray(policy) ? policy : String(policy ?? POLICY_NOTHING).split(';'))
427	    .map((t) => conjunctionParts(String(t).trim()).join(CONJUNCTION))
428	    .join(';');
429	
430	// --- the verdict --------------------------------------------------------------
431	
432	// The files no granular policy may cover except as comment-only edits: the
433	// sources the policy machinery itself is read from. Whatever an allow rule says,
434	// a run authorized by a list must not be able to rewrite what it is authorized
435	// to do. (`'anything'` — the vendored-converge lane — is deliberately exempt:
436	// the mount refresh replaces these files wholesale, and that lane's trust is the
437	// repo's delivery setting, not a diff class.)
438	//
439	// One narrow relaxation: such a file UNDER THE VENDORED MOUNT may be covered by
440	// a declared rule carrying `coversMountPolicySources` — the shape an adoption
441	// re-vendor has, where policy files arrive canon-authored inside the pack trees
442	// it copies. The flag rides merge-rules.json, which is itself guarded and
443	// owner-committed, so a run cannot grant it to itself; repo-owned policy
444	// sources (everything outside the mount) stay absolute.
445	const POLICY_SOURCES = /(^|\/)(merge-rules\.json|merge-policy\.mjs|workRules\/automerge-policy-scope\.mjs|tasks\/[^/]+\/task\.json)$/;
446	const VENDORED_MOUNT = /^\.claudinite\/shared\//;
447	
448	// The whole verdict over a diff. `entries` are `{ file, before, after }` (null
449	// side = added/deleted); `declaredRules` a Map from declaredMergeRules, with its
450	// `errors` passed through so a broken declaration fails any policy that names
451	// the broken pack's rule set. Returns { mergeable, why, files, problems }:
452	// `files` carries one line per changed file (its covering rule, or its
453	// violation), `problems` each refusal as { file, what } — file null for a
454	// whole-diff refusal — because a run that parks has to say what it parked over.
455	export function policyVerdict({ policy, entries, declaredRules = new Map(), ruleErrors = [] }) {
456	  const refuse = (problems, files = []) => ({
457	    mergeable: false, why: problems.map((p) => p.what).join('; '), files, problems,
458	  });
459	  const norm = normalizePolicy(policy);

